from dataclasses import dataclass, field
@dataclass
class P: xs:list=field(default_factory=list)
a=P(); b=P(); a.xs.append(1)
assert b.xs==[]

import pickle
x={'a':[1,2]}
assert pickle.loads(pickle.dumps(x))==x

from functools import cached_property
class A:
 @cached_property
 def x(self): return 3
assert A().x==3

import re
m=re.fullmatch(r'(?P<a>\d+)-(?P<b>\w+)','12-x')
assert m.groupdict()=={'a':'12','b':'x'}

from typing import Protocol,runtime_checkable
@runtime_checkable
class Sized(Protocol):
 def __len__(self)->int: ...
assert isinstance([],Sized)

from functools import lru_cache
@lru_cache(None)
def fib(n): return n if n<2 else fib(n-1)+fib(n-2)
assert fib(10)==55

from dataclasses import dataclass,asdict
@dataclass
class User: name:str; age:int
assert asdict(User('A',2))=={'name':'A','age':2}

from unittest.mock import patch
class Api:
 @staticmethod
 def get(): return 'real'
def f(): return Api.get()
with patch.object(Api,'get',return_value='fake'): assert f()=='fake'
assert f()=='real'

import json
payload={'x':{1,2}}; fixed={'x':sorted(payload['x'])}
assert json.loads(json.dumps(fixed))=={'x':[1,2]}

from functools import lru_cache
@lru_cache(None)
def total(xs): return sum(xs)
assert total((1,2,3))==6

